@@ -495,6 +495,36 @@ extern "C" void c_readhd_n(natb vetti[], natl primo, natb quanti)

 /// @todo Gestire l'operazione tenendo conto della buffer cache.
 // ( SOLUZIONE 2023-01-11
+	sem_wait(d->mutex);
+	for (natb i = 0; i < quanti; i++) {
+		natl block = primo + i;
+		buf_des *b = nullptr;
+		for (int j = 0; j < MAX_BUF_DES; j++) {
+			if (d->bufcache[j].full && d->bufcache[j].block == block) {
+				b = &d->bufcache[j];
+				break;
+			}
+		}
+		if (b) {
+			bufcache_promote(b);
+		} else {
+			int slot;
+			for (slot = 0; slot < MAX_BUF_DES; slot++) {
+				if (!d->bufcache[slot].full)
+					break;
+			}
+			if (slot == MAX_BUF_DES)
+				slot = d->lru;
+			b = &d->bufcache[slot];
+			b->block = block;
+			starthd_in(d, (natb*)b->buf, block, 1);
+			sem_wait(d->sincr);
+			b->full = true;
+			bufcache_promote(b);
+		}
+		memcpy((void*)(vetti + i * DIM_BLOCK), (const void*)b->buf, DIM_BLOCK);
+	}
+	sem_signal(d->mutex);
 //   SOLUZIONE 2023-01-11 )
 //   ESAME 2023-01-11 ]
 }
